import java.util.*;
class MVCC {record Version(int value,int version,String writer){}record Read(String key,Version row){}static class Tx{Integer snapshot;String state="active";Map<String,Integer>writes=new HashMap<>();List<Read>reads=new ArrayList<>();}String isolation;int clock;Map<String,List<Version>>versions=new HashMap<>();Map<String,Tx>transactions=new HashMap<>();MVCC(String isolation){this.isolation=isolation;for(String k:List.of("x","y"))versions.put(k,new ArrayList<>(List.of(new Version(1,0,null))));}
void begin(String id){if(transactions.putIfAbsent(id,new Tx())!=null)throw new IllegalArgumentException("ID reused");}Tx active(String id){Tx t=transactions.get(id);if(t==null||!t.state.equals("active"))throw new IllegalStateException("not active");if(t.snapshot==null)t.snapshot=clock;return t;}boolean snapshot(){return isolation.equals("repeatable-read")||isolation.equals("serializable");}
void write(String id,String key,int value){active(id).writes.put(key,value);}int read(String id,String key){Tx t=active(id);if(t.writes.containsKey(key))return t.writes.get(key);int limit=snapshot()?t.snapshot:clock;Version row=versions.get(key).get(0);for(Version v:versions.get(key))if(v.version()<=limit)row=v;t.reads.add(new Read(key,row));return row.value();}
int writeVersion(String id,String key,String candidate){return id.equals(candidate)?clock+1:versions.get(key).stream().filter(v->id.equals(v.writer())).findFirst().orElseThrow().version();}
boolean cycle(String candidate){Map<String,Tx>nodes=new HashMap<>();transactions.forEach((id,t)->{if(t.state.equals("committed")||id.equals(candidate))nodes.put(id,t);});Set<String>edges=new HashSet<>();for(var e:nodes.entrySet())for(Read r:e.getValue().reads){if(r.row().writer()!=null&&!r.row().writer().equals(e.getKey()))edges.add(r.row().writer()+":"+e.getKey());for(var w:nodes.entrySet())if(!w.getKey().equals(e.getKey())&&w.getValue().writes.containsKey(r.key())&&writeVersion(w.getKey(),r.key(),candidate)>r.row().version())edges.add(e.getKey()+":"+w.getKey());}for(String key:List.of("x","y")){List<String>writers=nodes.keySet().stream().filter(id->nodes.get(id).writes.containsKey(key)).sorted(Comparator.comparingInt(id->writeVersion(id,key,candidate))).toList();for(int i=1;i<writers.size();i++)edges.add(writers.get(i-1)+":"+writers.get(i));}return edges.contains("A:B")&&edges.contains("B:A");}
boolean commit(String id){Tx t=active(id);boolean conflict=snapshot()&&t.writes.keySet().stream().anyMatch(k->versions.get(k).get(versions.get(k).size()-1).version()>t.snapshot);if(conflict||(isolation.equals("serializable")&&cycle(id))){rollback(id);return false;}if(!t.writes.isEmpty()){clock++;for(var e:t.writes.entrySet())versions.get(e.getKey()).add(new Version(e.getValue(),clock,id));}t.state="committed";return true;}void rollback(String id){Tx t=active(id);t.writes.clear();t.state="aborted";}}
// IDs A/B, keys x/y, validated operations. Full SSI/predicates/locks/recovery are outside this model.
